class Dish {
  #ingredients = [];

  constructor(name, ingredients) {
    this.name = name;
    this.#ingredients = ingredients;
  }

  getTotalCalories() {
    return this.#ingredients.reduce((total, ingredient) => {
      const calories = ingredient.caloriesPerServing || 0;
      const servings = ingredient.servings || 0;
      return total + (calories * servings);
    }, 0);
  }
}

// Example Usage
const ingredientsForStirFry = [
  { name: "Rice", caloriesPerServing: 130, servings: 2 },
  { name: "Chicken Breast", caloriesPerServing: 165, servings: 1.5 },
  { name: "Broccoli", caloriesPerServing: 55, servings: 1 }
];

const stirFry = new Dish("Chicken Stir-Fry", ingredientsForStirFry);
// Expected: 130*2 + 165*1.5 + 55*1 = 260 + 247.5 + 55 = 562.5
// console.log(`${stirFry.name} total calories: ${stirFry.getTotalCalories()}`);

const ingredientsForSalad = [
  { name: "Lettuce", caloriesPerServing: 15, servings: 1 },
  { name: "Cucumber", caloriesPerServing: 10, servings: 0.5 }
];
const simpleSalad = new Dish("Simple Salad", ingredientsForSalad);
// console.log(`${simpleSalad.name} total calories: ${simpleSalad.getTotalCalories()}`);

